const input = $json.body ?? $json;
const jobId = input.jobId;
if (!jobId || !/^[0-9a-f-]{36}$/i.test(jobId)) throw new Error('Invalid jobId');
return [{json: {...input, jobId}}];

const rows = $input.first().json;
const job = Array.isArray(rows) ? rows[0] : rows;
if (!job?.script_json) throw new Error('No script found for job');
const VOICES = { 'Warm narrator': 'af_heart', 'Studio neutral': 'am_michael', 'Energetic guide': 'af_nova' };
const script = job.script_json;
const text = String(Array.isArray(script.scenes) ? script.scenes.map(s => s.narration).filter(Boolean).join(' ') : '').trim();
if (!text) throw new Error('No narration text available');
const requestedDuration = Number(job.brief_json?.duration);
const sceneDurations = Array.isArray(script.scenes) ? script.scenes.map(scene => Number(scene.durationSeconds)) : [];
if (!sceneDurations.length || sceneDurations.some(duration => !Number.isFinite(duration) || duration <= 0)) throw new Error('INVALID_SCENE_DURATION');
const sceneDuration = Math.round(sceneDurations.reduce((sum, duration) => sum + duration, 0) * 100) / 100;
if (!Number.isFinite(requestedDuration) || requestedDuration <= 0) throw new Error('INVALID_REQUESTED_DURATION');
if (Math.abs(sceneDuration - requestedDuration) > 0.01) throw new Error('SCENE_DURATION_MISMATCH: requested=' + requestedDuration + ', scenes=' + sceneDuration);
const tone = String(job.brief_json?.voiceTone || '').trim();
const voiceRates = { 'Warm narrator': 140, 'Studio neutral': 132, 'Energetic guide': 132 };
const voiceWordsPerMinute = Number(script.durationValidation?.voiceWordsPerMinute || voiceRates[tone] || 140);
const targetWords = Math.round(requestedDuration * voiceWordsPerMinute / 60);
const minWords = Math.floor(targetWords * 0.98);
const maxWords = Math.ceil(targetWords * 1.02);
const wordCount = text.split(/\s+/).filter(Boolean).length;
if (wordCount < minWords || wordCount > maxWords) throw new Error('NARRATION_WORD_COUNT_MISMATCH: actual=' + wordCount + ', expected=' + minWords + '-' + maxWords);
const ttsVoice = VOICES[tone] || (tone.includes('Warm') ? 'af_heart' : tone.includes('Studio') ? 'am_michael' : tone.includes('Energetic') ? 'af_nova' : 'af_heart');
return [{ json: { jobId: job.id, text, ttsVoice, requestedDuration, sceneDuration, wordCount, targetWords } }];

const jobId = $('Validate Input').first().json.jobId;
const input = $input.first();
const binaryData = input.binary?.data;
if (!binaryData?.data) {
  const jsonResponse = input.json;
  if (jsonResponse?.audio_url || jsonResponse?.public_url) return [{ json: { jobId, audio_url: jsonResponse.audio_url || jsonResponse.public_url, local_path: null, file_size: null } }];
  throw new Error('No binary or audio URL received from TTS');
}
const localPath = '/data/jobs/' + jobId + '/narration.wav';
return [{ json: { jobId, local_path: localPath, file_size: Buffer.from(binaryData.data, 'base64').length }, binary: input.binary }];

const jobId = $('Validate Input').first().json.jobId;
const requestedDuration = $('Extract Narration Text').first().json.requestedDuration;
const localPath = '/data/jobs/' + jobId + '/narration.wav';
const fs = require('fs');
const { spawnSync } = require('child_process');

if (!fs.existsSync(localPath)) {
  throw new Error('Audio file not found: ' + localPath);
}

const probe = spawnSync('ffprobe', [
  '-v', 'error',
  '-show_entries', 'format=duration',
  '-of', 'default=noprint_wrappers=1:nokey=1',
  localPath
], { encoding: 'utf8' });

if (probe.error || probe.status !== 0) {
  throw new Error('ffprobe failed: ' + (probe.stderr || probe.error));
}

const actualDuration = parseFloat(probe.stdout.trim());
if (!Number.isFinite(actualDuration) || actualDuration <= 0) {
  throw new Error('Invalid audio duration: ' + probe.stdout);
}

const targetDuration = Number(requestedDuration);
const tolerance = 0.05;
const ratio = actualDuration / targetDuration;

if (Math.abs(ratio - 1) > tolerance) {
  const tempo = Math.min(Math.max(ratio, 0.5), 2.0);
  const tempPath = localPath + '.corrected.wav';
  const result = spawnSync('ffmpeg', [
    '-y', '-i', localPath,
    '-af', 'atempo=' + tempo,
    '-ar', '24000',
    tempPath
  ], { encoding: 'utf8', timeout: 60000 });

  if (result.error || result.status !== 0) {
    throw new Error('ffmpeg atempo failed: ' + (result.stderr || result.error));
  }

  fs.copyFileSync(tempPath, localPath);
  fs.unlinkSync(tempPath);

  const verifyProbe = spawnSync('ffprobe', [
    '-v', 'error',
    '-show_entries', 'format=duration',
    '-of', 'default=noprint_wrappers=1:nokey=1',
    localPath
  ], { encoding: 'utf8' });
  const verifiedDuration = parseFloat(verifyProbe.stdout.trim());

  return [{
    json: {
      jobId,
      local_path: localPath,
      original_duration: actualDuration,
      target_duration: targetDuration,
      corrected_duration: verifiedDuration,
      tempo_applied: tempo,
      corrected: true
    }
  }];
}

return [{
  json: {
    jobId,
    local_path: localPath,
    original_duration: actualDuration,
    target_duration: targetDuration,
    corrected_duration: actualDuration,
    tempo_applied: 1.0,
    corrected: false
  }
}];

const input = $json.body ?? $json;
const jobId = input.jobId ?? input.id;
if (!jobId || !input.workerId || !input.leaseToken || input.attemptNumber == null || input.pipelineRevision == null) throw new Error('LEASE_CONTEXT_REQUIRED');
const stage = 'generate_voice';
const itemKey = input.itemKey ?? ('job' === 'scene_set' ? 'all-scenes' : 'job');
const canonical = JSON.stringify({jobId, pipelineRevision: input.pipelineRevision, stage, itemKey, revision: input.currentRevision ?? input.pipelineRevision});
return [{json: {...input, jobId, stage, itemKey, stageHashInput: canonical, workerId: input.workerId, leaseToken: input.leaseToken, attemptNumber: Number(input.attemptNumber), pipelineRevision: Number(input.pipelineRevision)}}];

const {stageHashInput, ...context} = $('Hash Stage Input').first().json;
const result = $json;
return [{json: {...context, stageState: result.state, stageRunId: result.stage_run_id, runToken: result.run_token, cachedOutput: result.output}}];

const context = $('Merge Stage Context').first().json;
if ($json.permitted !== true) throw new Error('EXTERNAL_ATTEMPT_LIMIT');
return [{json: {...context, externalAttempt: $json.attempt_number}}];

const context = $('Merge Stage Context').first().json;
if (context.stageState !== 'CACHED_SUCCESS') throw new Error('STAGE_RECONCILIATION_REQUIRED');
return [{json: {success: true, cached: true, jobId: context.jobId, stage: context.stage, stageRunId: context.stageRunId, output: context.cachedOutput}}];

const jobId = $('Validate Input').first().json.jobId;
const fs = require('fs');
const path = require('path');

const audioPath = '/data/jobs/' + jobId + '/narration_custom.wav';
if (!fs.existsSync(audioPath)) {
  throw new Error('Custom audio file not found: ' + audioPath);
}

const stats = fs.statSync(audioPath);
if (stats.size === 0) {
  throw new Error('Custom audio file is empty');
}

// Read the audio file as base64 for n8n binary handling
const audioBuffer = fs.readFileSync(audioPath);
const audioBase64 = audioBuffer.toString('base64');

// Get duration from job (already measured during upload)
const job = $('Get Script').first().json;
const uploadedDuration = job.uploaded_audio_duration || job.effective_duration;
if (!uploadedDuration) {
  throw new Error('Uploaded audio duration not found in job');
}

return [{ json: { ...job, local_path: audioPath, audio_base64: audioBase64, uploaded_duration: uploadedDuration }, binary: { data: { data: audioBase64, mimeType: 'audio/wav' } } }];
